#include <iostream>
#include <string>

int porValor(int x) {
    return x + 1;
}

void porReferencia(int& x) {
    ++x;
}

void porPuntero(int* x) {
    ++(*x);
}

void porConstRef(const std::string& texto) {
    std::cout << "longitud: " << texto.size() << '\n';
}

int main() {
    int a = 1;
    int b = 1;

    a = porValor(a);        // a sigue siendo 1 hasta la asignacion
    porReferencia(b);       // modifica b
    porPuntero(&b);         // modifica b otra vez
    porConstRef("hola");    // no copia la cadena

    std::cout << a << ' ' << b << '\n';
    return 0;
}

