#include <iostream>

int area(int lado) {
    return lado * lado;
}

int area(int ancho, int alto) {
    return ancho * alto;
}

double area(double radio) {
    return 3.141592653589793 * radio * radio;
}

int main() {
    std::cout << area(4) << '\n';       // cuadrado
    std::cout << area(3, 5) << '\n';    // rectangulo
    std::cout << area(2.5) << '\n';     // circulo
    return 0;
}

#include <iostream>

long long potencia(int base, int exponente) {
    if (exponente == 0) {
        return 1;
    }
    return base * potencia(base, exponente - 1);
}

int mcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return mcd(b, a % b);
}

int main() {
    std::cout << "2^10 = " << potencia(2, 10) << '\n';
    std::cout << "mcd(48, 18) = " << mcd(48, 18) << '\n';
    return 0;
}

#include <iostream>

int factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

int main() {
    std::cout << factorial(3) << '\n';
    return 0;
}

