#include <iostream>

int sumaDigitos(int n) {
    if (n < 10) {
        return n;
    }
    return (n % 10) + sumaDigitos(n / 10);
}

int main() {
    std::cout << sumaDigitos(407) << '\n';
    std::cout << sumaDigitos(9999) << '\n';
    return 0;
}

